cards=[]
cards.append(compact('xiao_na','小纳尔逊','小纳尔逊是卫斯理旧友纳尔逊的儿子，既承接了私人信任，也在情报体系中形成比父亲更鲜明的职业立场。父亲去世时，他同意验尸，并相信卫斯理对方天的判断；成年后的他却不会只因为父辈交情就无条件公开机构秘密。《命运》中，他迅速辨认潜入者装备、搜查和施压，愿付高价取得宋天然的资料，显出训练、资源和对情报价值的敏感。《游戏》由他组织多国追查，亲自随韩因潜入黑海；面对失去动力的潜艇，他也会恐惧，却先努力稳住同伴。巴曼承认杀死出言顶撞的加丹时，小纳庆幸自己忍住了辱骂，说明克制有时来自很具体的求生判断。后来他的职位日高，在《双程》的反恐围捕中认出卫斯理，召集有关人员听取解释，并主持会议明确支持双程生命的说法。这份信任并不能令所有机构接受异常解释，也没能立即免除黄堂的法律困境。终局卡保留官员、调查者与老朋友三重身份的拉扯，不把美国国家机器当作其个人火力，也不把相信卫斯理写成永远不核实其他证据。','《双程》仍为美国高级情报人物，亲自协调国际反恐会议并支持卫斯理解释','重要配角','完成情报任务并在已验证的私人信用与制度责任之间作决定','说话干练，先问可验证的资料、来源与资源需求','遭遇技术失控时先稳定同伴；生命受威胁时克制无益挑衅','国家立场不等于全知，信任可以推动听证但不能取代证据',[ab('情报调查与现场处置','辨认装备、审查资料、搜查嫌疑者并安排跨机构调查','依赖实际权限、同僚合作和器材；不是无限监视或随时调用军队'),ab('危机沟通','在黑海行动和反恐误捕中协调不同人员，解释异常事实','无法让所有机关必然接受其判断，不能抹除司法程序')],[ev('004',6220,6230,'父死后同意验尸'),ev('004',6330,6332,'信任卫判断'),ev('064',943,993,'装备辨识与现场行动'),ev('069',2207,2217,'失控中先安抚韩因'),ev('117',2551,2614,'终局身份和支持会议')],profile='investigator',aliases=['小纳','小纳尔逊中校']))
cards.append(compact('gailei','盖雷夫人','盖雷夫人是东欧阵营地位极高的老情报工作者，外表瘦小衰老，眼神和判断却始终机警。她在《命运》中没有公开姓名，以一通立陶宛语电话证明能释放宋天然，也接受了无法搬走整座大山的现实；《游戏》才明确前次相遇与她是同一个人。她会利用友人失踪和秘密引起卫斯理兴趣，也安排持续监听及紧急无线电后手，不因语气平淡就缺乏控制局面的企图。巴曼的核爆威胁超出常规政治后，她反对最高当局把希望建立在潜艇已经毁灭的假设上，坚持寻求卫斯理协助，甚至承认此举未获上级赞同。得知两位将领被杀、遗体可能被毁时，她一度浑身发抖，并非无情机器；恢复后仍能继续协调。终局接受释放官兵换取消核爆的安排，也看出继续追问卫斯理不会得到岩洞秘密，选择不纠缠。卡片保留政治手腕与灾难面前的理性合作，不把国家设备、传闻中的年龄或神秘名声转换成超人体魄。她能够承认有比阵营竞争更紧迫的共同危机，却不会因此突然失去保密习惯。','《游戏》完成官兵交换与消灾安排；后作提及不证明新增行动或能力',['重要配角','阶段性对立者'],'维护所属体系安全，同时避免政治自欺造成无法挽回的灾难','语调平静，习惯以信息差、暗示和提前安排争取主动','危机超出机构常规时寻求外援，强烈震惊后仍恢复协调','不能把没有证据的乐观假设当作已经排除危险',[ab('情报统筹与后备通信','调阅资料、安排监控与紧急信号，协调最高决策及释放人员','权限属于机构，手下会失联和死亡，不能获得所有未知技术'),ab('谈判识人','识别对象的兴趣与拒绝底线，以有限让步实现目标','并非读心，面对巴曼与外星技术多次缺乏事实')],[ev('064',1238,1279,'未具名老妇的权力和交涉'),ev('069',1287,1320,'身份与上次命运事件明确连接'),ev('069',1816,1845,'拒绝无证假设及通信后手'),ev('069',2088,2111,'震惊与恢复'),ev('069',3177,3196,'最终协商与停止追问')],profile='expert',aliases=['盖雷老妇人']))
cards.append(compact('han_yin','韩因','韩因是法国海军中尉，受派驾驶性能优良的小型潜艇，与小纳尔逊共同追查黑海失踪案。他年轻、有技术自信，对情报工作抱着近乎游戏的兴奋，主动提议回程顺道探看俄国潜艇，让小纳也为之心动。可这份好奇并没有完全压倒专业判断：接近魔鬼暗礁时，他明确说明进去容易、出来困难，知道动力极限和漩涡风险，最终操纵潜艇后退。再次卷入时，一万八千匹马力的设备突然失去效用，他惊叫、喘息、无法回答，显示熟悉机器并不等于能够应付超出设计的力量。被巴曼接入异常潜艇后，他一度以为对方是外星人，听到核灾计划才意识到自己已不是在玩安全的冒险。获释后，他如实转述设备失控，起初不放心把潜艇交给卫斯理，后来亲见对方迅速掌握操作而改变看法。终局保留海军驾驶员的知识、年轻人的热情与受惊后的谨慎，不把法国军方的潜艇永久算成他的肉身，也不让他重复以莽撞证明勇敢。','《游戏》生还并协助卫斯理熟悉借用潜艇，未取得巴曼的外星基地技术','主角','完成潜艇调查任务，并证明技术与勇气能派上用场','兴致勃勃解释设备，愿探索新任务，也爱提出大胆主意','设备接近极限时明确建议撤离，彻底失控时会惊恐并接受协助','熟悉机器的操作边界比单纯逞强更能保命',[ab('小型潜艇驾驶','掌握潜航、动力管理、自动驾驶及应急舱操作','依赖潜艇、能源和海况，无法抵抗异常停机或巨大漩涡'),ab('设备教学与任务报告','能向非海军专业者说明关键操纵和危险','技术理解限于已知设备，不会即刻破解外星装置')],[ev('069',1083,1124,'军衔、操作与冒险提议'),ev('069',1200,1248,'判断海况和撤离'),ev('069',2207,2289,'恐惧、失控及紧急开舱'),ev('069',2371,2417,'报告和交付潜艇')],profile='expert'))
cards.append(compact('jia_dan','加丹','加丹是土耳其年轻情报人员，褐棕色头发柔软，初次在多国会议发言时会脸红，谈及国家所受威胁却又清晰有力。他提供黑海舰队将领活动资料，也不愿被大国同行轻视。追查班提斯失踪时，他发现草率搜寻与空船漂出暗礁的矛盾，亲往海岸巡逻队和潜水者酒吧求援，却缺乏对当地潜水风险和行业规则的了解。他以高薪、爱国责任乃至讥讽激励众人，仍无法说服别人去送死；最后求助小纳安排适当潜艇，本来是一条更稳妥的路线。两名英国潜水员突然愿意受雇，他便因机会来得太快而冒险出海，未能继续每天联络。巴曼后来承认，原想利用他向美国传话，因他当面斥责其疯狂而将他杀死。卡片保留这个既有分析能力、责任心又会被自尊和急切推动的年轻人，不把他的死亡归为能力低下，也不美化他以民族勇气施压民间潜水员的做法。演绎采用最后可行动形态并标注恢复，让他能够在新场景中争论、求助和判断代价，而不是只能重演死亡。','《游戏》被巴曼杀害；参战恢复最后可行动的人类形态并保留终局认知','主角','查清海域威胁并维护国家安全，渴望工作被认真对待','认真搜集报告，受到轻视时急于解释和证明','机会受阻时可能以高价与激将催促他人，直面疯狂计划会愤怒斥责','勇气必须与实际设备及自愿承险相配，不能只靠羞辱争取配合',[ab('情报汇集与矛盾检查','整理舰队活动、比对失踪过程并识别搜救解释的漏洞','并非潜水专家，知识不足会影响现场风险评估'),ab('地方联络与招募','拜访巡逻机构、潜水员及盟国同行寻求资源','没有无限军权，别人可以拒绝，外交风险限制正规军事介入')],[ev('069',136,174,'会议身份和资料'),ev('069',601,687,'调查、招募与求助'),ev('069',691,715,'出海失踪'),ev('069',2355,2361,'巴曼承认杀害')],profile='ordinary'))
