cards.append(compact('ban_tisi','班提斯','班提斯是来自葡萄牙的深水潜水员，瘦削而显得神经质，独自到锡诺普寻找海中宝藏。他对自己的发现既兴奋又戒备，连酒吧老板的普通祝福都误会成别人已经知道目标，要求对方保密。发现俄国潜艇后，他不敢完全相信所见，也意识到那不是寻宝者通常应在此处遇到的东西，借酒缓解紧张并向老情人透露少量线索。他说自己会再次去弄清，随后出海失踪，船与潜水装备却被完整找回，使周围人无法用普通潜水事故解释。后来巴曼向小纳承认，潜水员曾看到其潜艇，自己一有机会便将他杀死，失踪的谜因此成为保密暴力的后果。卡片保留专业潜水经验与寻宝冲动，但不把潜艇里的外星技术归于他，也不编造他潜入岩洞、掌握秘密后的经历。若在新的舞台参战，需要明确恢复最后可行动的肉身并保留知道自己遇害的终局记忆。他面对异常可以更认真地留下记录、要求备援，却仍会因为独占发现的欲望而犹疑，不必变成毫无风险偏好的标准调查者。','《游戏》因看见巴曼潜艇被杀；参战恢复最后可行动的人类形态并保留终局记忆','主角','独自发现海底财富与未知事物，同时守住自己的线索','敏感、保密，谈到发现时兴奋又犹疑，可能借酒缓解压力','发现超出预期的东西时想再次核实，却容易低估被看见本身的危险','独占发现与保证求援不能兼得，专业潜水也不能防住蓄意杀人',[ab('深水潜水与寻宝','以潜水经验搜索海域并辨认异常潜艇','需要适当装备和海况；没有超人生理或自由进入致命漩涡的证据'),ab('异常观察','能描述潜艇国别与出现地点不寻常，尝试再次核实','紧张、饮酒与过度保密影响有效求援，未完整掌握事件内幕')],[ev('069',384,451,'外貌、职业、保密与潜艇发现'),ev('069',711,729,'装备留船的失踪特征'),ev('069',2355,2359,'确认被巴曼杀害')],profile='ordinary'))
cards[-1]['adaptations'].append({'change':'恢复最后可行动形态并保留终局记忆','reason':'原文明确遇害，后日谈接口不能冒称原作复活。','power_impact':'仅恢复活动，不增加抗伤能力。'})
for id,name,rank,detail in [('pulunkefu','普罗科夫','黑海舰队司令员','他最初顾虑巴曼与最高层关系，虽不满仍表面圆滑；后来转为强硬，甚至说与叛徒同归于尽也是军人职责。'),('weilasiji','维拉斯基','黑海舰队参谋长','他协助司令策划逼迫与控制，语气阴森严厉，但潜艇异常时提出先返回基地，较早流露求生犹豫。')]:
    bio=name+'是'+rank+'，卷入巴曼借外星技术部署核爆的危机。面对明显超过常规军事能力的计划，他与同僚先怀疑、再由专家核验，最终不得不承认真有足以改变地理的危险装置。'+detail+'上级把说服巴曼取消计划的责任交给两人，他们以挑衅其自尊的办法安排观察潜艇，拘留原艇官兵、换上可靠人员，并试图找出控制装置。发现秘密舱门和爆炸警告后，他们没有真正解决技术问题，却仍要用权力和威胁强迫巴曼开门。潜艇早已被彻底改装，普通驾驶经验不再适用，通讯最终在巨响中中断。后文由巴曼提出可以送出两人的遗体，确认他们已经死亡。卡片将此人列作阶段性对立者，并不把阻止灾难本身当作邪恶；其问题在于政治权力与武力逼迫不能替代对未知技术的理解。参战恢复最后可行动的人类形态，保留终局记忆，舰队与军衔均须有相应制度才有实际作用。'
    c=compact(id,name,bio,'《游戏》在巴曼控制的潜艇事件中死亡；参战恢复最后可行动的人类形态并保留终局记忆','阶段性对立者','制止失控核计划、维护军事指挥权与自身责任','以军令、层级和专家报告安排工作','控制受挑战时可能强迫服从，面对技术失控才暴露恐惧或犹疑','合法权力并不自动赋予理解和控制所有设备的能力',[ab('军事组织与行动设计','调动授权人员接管潜艇、拘押原有官兵并搜查设备','依赖制度授权和实际部队；陌生改装设备会使部署失效')],[ev('069',1655,1693,'计谋、授权及接管'),ev('069',1730,1792,'强迫开舱与失控'),ev('069',2103,2108,'遗体确认死亡')],profile='investigator')
    c['adaptations'].append({'change':'恢复最后可行动形态并保留终局记忆','reason':'原作死亡而任务需要后日谈参战。','power_impact':'军权和舰艇不随复原自动获得。'})
    cards.append(c)
cards.append(compact('lao_qingren','老情人','老情人是锡诺普海洋酒吧的主人，真名不详，七十岁以上仍精神旺盛，高大骨架外却已是松弛肌肉与皱皮。他喜欢听来客说话，也愿让仍能点酒的客人继续坐下，曾为欣赏黑海落日改造酒吧，却发现客人往往更关心酒杯。年轻时的潜水经验使他懂得寻宝者的兴奋和失望，他自述的无辅助深潜纪录却没有旁证，不能作为超人事实。班提斯透露潜艇时，他先以经验判断对方在吹嘘，随后仍追问并记住异常细节。加丹高价招募潜水员遭拒，他帮助说明行规，也直接指出死人无法享受报酬，反对把无必要的送命叫作勇敢。这个老人不是无所不知的贤者：他会误判新人、嘲讽外行，也有刊登照片后的自得，却确实知道地方群体怎样感受风险。卡片保留他作为海边生活与专业经验见证者的独立叙事位置，不把善于谈天等同情报机关，也不让年轻时的传说抵销老年身体限制。新的冒险中，他可以提供联系人和经验，是否亲自涉险则应由身体与真实条件决定。','《游戏》仍经营海洋酒吧，未取得潜艇及岩洞秘密','主角','维持潜水者交流的场所，理解来客并避免无谓送命','好客健谈，爱欣赏海景，也会用玩笑试探外行','年轻人以金钱或民族荣誉逼人冒险时直言驳斥','专业者有权拒绝风险，热情和传闻不能替代可行条件',[ab('潜水经验与地方交流','凭长期接待经验识别行业习惯、危险海域和寻宝者心态','无旁证的旧纪录不算实际能力，年老体能不等同青年状态'),ab('倾听与风险劝说','记住醉客异常叙述，向调查者解释潜水人的拒绝','会先入为主误判，没有读心或保证人人接受劝说')],[ev('069',356,379,'外貌、酒吧与无旁证纪录'),ev('069',406,456,'听班提斯叙述和误判'),ev('069',640,676,'拒绝用报酬与爱国论证送命')],profile='ordinary'))
save(cards)
